#!/usr/bin/env sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# Generated by build.py from recipe.yml for recipe http-tell-which-listener-was-used. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p site
cat > site/report.csv <<'EOF'
id,total
1,40
EOF
printf '%s\n' 'listener-recipe-control-token-0123456789' > token.txt
printf '%s\n' 'Authorization: Bearer listener-recipe-control-token-0123456789' > control.hdr
cat > which-listener.sh <<'EOF'
#!/bin/sh
# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.
# For each exchange: the listen URL that took it, from surl's control endpoint, beside what
# the trace says (the listen URL on its Exchange opened line, and for HTTP the Host header the client sent).
# Run: sh which-listener.sh <control URL>   (control.hdr holds the token header)
control=$1
count() { curl -s -H @control.hdr "${control}v1/events?kind=$1" | grep -o '"exchange_id"' | grep -c .; }

# The record is whole once every exchange that started has ended: wait, at most 10 s.
tries=0
until [ "$(count exchange_ended)" -eq "$(count exchange_started)" ]; do
  tries=$((tries + 1))
  if [ "$tries" -gt 50 ]; then echo "the exchanges did not end within 10 s"; exit 1; fi
  sleep 0.2
done

curl -s -H @control.hdr "${control}v1/events?kind=exchange_started" |
  grep -o '"exchange_id":[0-9]*,"listen_url":"[^"]*"' | tr -d '"' | sed 's/exchange_id://; s/,listen_url:/ /' |
  while read -r id url; do
    listener=$(grep "^#$id \* Exchange $id opened: " trace.txt | sed 's/.* opened: [a-z]* on \([^ ]*\) from .*/\1/')
    host=$(awk -v mark="#$id " '
      index($0, "#") == 1 { inside = (index($0, mark "<= Recv") == 1); next }
      inside && / Host: / { sub(/.* Host: /, ""); sub(/\r$/, ""); print; exit }' trace.txt)
    echo "exchange $id: $url  trace: $listener${host:+, Host $host}"
  done
EOF
surl --allow-anonymous --directory site --log-file surl.log --trace-ascii trace.txt --control http://127.0.0.1:8083/ --control-token-file token.txt http://127.0.0.1:8080/ http://127.0.0.1:8081/ ftp://127.0.0.1:8082/ &
sleep 1
curl -s --retry 30 --retry-connrefused --retry-delay 1 -o /dev/null -H @control.hdr http://127.0.0.1:8083/v1/events
sh which-listener.sh http://127.0.0.1:8083/
kill $(jobs -p)
